from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        # Precompute factorials
        fact = [1] * (n + 1)
        for i in range(2, n + 1):
            fact[i] = fact[i-1] * i

        # Count odd and even numbers in [1, n]
        odd_count = (n + 1) // 2
        even_count = n // 2

        # Available numbers
        available_odd = list(range(1, n+1, 2))
        available_even = list(range(2, n+1, 2))

        result = []
        last_parity = -1  # -1 for the first element

        for i in range(n):
            if i == 0:
                # For the first element, iterate candidates in increasing order
                candidates = sorted(available_odd + available_even)
            else:
                # For i>0, the required parity is the opposite of last_parity
                if last_parity == 1:
                    candidates = available_even
                else:
                    candidates = available_odd

            found = False
            for cand in candidates:
                p = cand % 2

                # For the first element (i=0), we must check if the pattern is valid.
                if i == 0:
                    if p == 1:
                        # Pattern starting with odd: valid for any n
                        ways = fact[odd_count-1] * fact[even_count]
                    else:
                        # Pattern starting with even: valid only if n is even
                        if n % 2 == 1:
                            ways = 0
                        else:
                            ways = fact[odd_count] * fact[even_count-1]
                else:
                    # For i>0, the pattern is already fixed by the first element, so we just compute the ways.
                    # The required parity is p (which is the opposite of last_parity).
                    # The remaining counts: 
                    #   same_parity = (if p==1 then odd_count else even_count)
                    #   other_parity = (if p==1 then even_count else odd_count)
                    # But note: we are about to choose one number of parity p, so:
                    same_rem = odd_count if p==1 else even_count
                    other_rem = even_count if p==1 else odd_count
                    same_rem -= 1
                    ways = fact[same_rem] * fact[other_rem]

                if ways == 0:
                    # Skip this candidate
                    continue

                if k <= ways:
                    result.append(cand)
                    if p == 1:
                        available_odd.pop(available_odd.index(cand))
                        odd_count -= 1
                    else:
                        available_even.pop(available_even.index(cand))
                        even_count -= 1

                    last_parity = p
                    found = True
                    break
                else:
                    k -= ways

            if not found:
                return []

        return result

from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        if n == 0:
            return 0
        m = len(grid[0])
        if m == 0:
            return 0

        max_len = 0

        # Directions: (dr, dc)
        # 0: top-left to bottom-right (1, 1)
        # 1: bottom-right to top-left (-1, -1)
        # 2: top-right to bottom-left (1, -1)
        # 3: bottom-left to top-right (-1, 1)
        directions = [(1, 1), (-1, -1), (1, -1), (-1, 1)]

        # Clockwise turn mapping: current_dir -> next_dir
        clockwise_turn = {0: 2, 1: 3, 2: 0, 3: 1}

        # Precompute L1 and L2
        # L1[i][j][dir]: length of sequence starting at (i,j) in direction `dir` that matches 2,0,2,0,...
        # L2[i][j][dir]: length of sequence starting at (i,j) in direction `dir` that matches 0,2,0,2,...
        L1 = [[[0]*4 for _ in range(m)] for _ in range(n)]
        L2 = [[[0]*4 for _ in range(m)] for _ in range(n)]

        for d in range(4):
            dr, dc = directions[d]
            # Determine iteration order
            if dr > 0:
                i_start, i_end = n-1, -1
                step_i = -1
            else:
                i_start, i_end = 0, n
                step_i = 1
            if dc > 0:
                j_start, j_end = m-1, -1
                step_j = -1
            else:
                j_start, j_end = 0, m
                step_j = 1

            for i in range(i_start, i_end, step_i):
                for j in range(j_start, j_end, step_j):
                    ni, nj = i + dr, j + dc
                    if 0 <= ni < n and 0 <= nj < m:
                        if grid[i][j] == 2:
                            L1[i][j][d] = 1 + L2[ni][nj][d]
                        else:
                            L1[i][j][d] = 0
                        if grid[i][j] == 0:
                            L2[i][j][d] = 1 + L1[ni][nj][d]
                        else:
                            L2[i][j][d] = 0
                    else:
                        if grid[i][j] == 2:
                            L1[i][j][d] = 1
                        else:
                            L1[i][j][d] = 0
                        if grid[i][j] == 0:
                            L2[i][j][d] = 1
                        else:
                            L2[i][j][d] = 0

        # For each starting point
        for i in range(n):
            for j in range(m):
                if grid[i][j] == 1:
                    for d1 in range(4):
                        dr1, dc1 = directions[d1]
                        next1 = (i + dr1, j + dc1)
                        if 0 <= next1[0] < n and 0 <= next1[1] < m and grid[next1[0]][next1[1]] == 2:
                            initial_path_length = 1 + L1[next1[0]][next1[1]][d1]
                        else:
                            initial_path_length = 1

                        # Try turning at each step k from 0 to initial_path_length-1
                        for k in range(initial_path_length):
                            turn_i, turn_j = i + k * dr1, j + k * dc1
                            d2 = clockwise_turn[d1]
                            dr2, dc2 = directions[d2]
                            next2 = (turn_i + dr2, turn_j + dc2)

                            if 0 <= next2[0] < n and 0 <= next2[1] < m:
                                if (k+1) % 2 == 1:
                                    length_new = L1[next2[0]][next2[1]][d2]
                                else:
                                    length_new = L2[next2[0]][next2[1]][d2]
                            else:
                                length_new = 0

                            total_length = (k+1) + length_new
                            if total_length > max_len:
                                max_len = total_length

        return max_len
